// Verifies x-meetsum-signature-v2 (t=<unix>,v1=<hex HMAC-SHA256(secret, t + "." + rawBody)>)
// and stops the workflow on a mismatch or a timestamp more than 5 minutes off.
const crypto = require('crypto')
const secret = $env.MEETSUM_WEBHOOK_SECRET
if (!secret) throw new Error('Set MEETSUM_WEBHOOK_SECRET to the subscription secret')
for (const item of $input.all()) {
  const headers = item.json.headers ?? {}
  const raw = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body)
  const parts = Object.fromEntries(String(headers['x-meetsum-signature-v2'] ?? '').split(',').map((part) => part.trim().split('=')))
  const t = Number(parts.t)
  if (!Number.isInteger(t) || Math.abs(Date.now() / 1000 - t) > 300) throw new Error('MeetSum signature: timestamp outside the 5 minute window')
  const expected = crypto.createHmac('sha256', secret).update(`${t}.${raw}`).digest('hex')
  const given = Buffer.from(String(parts.v1 ?? ''))
  if (given.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(expected), given)) throw new Error('MeetSum signature mismatch')
}
return $input.all()
